sys_script_client.script:
function onLoad() {

    if (g_form.getValue('hr_service') == '5227b08f2f4b60d04cbeb1e72799b659') { //If current case type is Safety Complaint
        g_form.removeOption('rw_whsc_decision', 'cons_not_reached');
        g_form.removeOption('rw_whsc_decision', 'no_danger');
        g_form.removeOption('rw_whsc_decision', 'danger');
        g_form.removeOption('rw_whsc_decision', 'ref_not_permitted');
        if (g_lang == "en") {
            g_form.addOption('rw_whsc_decision', 'Founded', 'Founded');
            g_form.addOption('rw_whsc_decision', 'Not Founded', 'Not Founded');
            g_form.addOption('rw_whsc_decision', 'Could not agree', 'Could not agree');
        } else {
            g_form.addOption('rw_whsc_decision', 'Founded', 'Établi');
            g_form.addOption('rw_whsc_decision', 'Not Founded', 'Non Établi');
            g_form.addOption('rw_whsc_decision', 'Could not agree', "Ne pouvait pas être d'accord");
        }
    }

}
